### RECURSION ###

# Please complete the function to recursively compute 
# whether the binary tree is symmetric 
# (i.e., the left subtree is a mirror-image of the right subtree)
# Parameters: root - TreeNode object of root node with fields: root.left, 
#       5                                                      root.right, 
#     3    3                                                   root.val
#    2  1 1  2
def is_symmetric(root) -> bool:
    def helper(a, b):
        # Base case
        if a is None and b is None:
            return True
        if a is None or b is None:
            return False
        if a.val != b.val:
            return False
        # Active flow
        return helper(a.right, b.left) and helper(a.left, b.right)
    return helper(root, root)qq
